    fn dynamic(&mut self,value:&DslValue,depth:u16,output:&mut Output)->Result<(),OutputError>{if depth>self.options.limits.max_depth.min(64){return Err(ValueError::new(ValueRefusalKind::DepthLimit,"Pack dynamic output depth exceeds limit").into())}self.control.checkpoint()?;match value{
        DslValue::Null=>output.byte(TAG_NULL,self.control),DslValue::Bool(value)=>output.byte(if *value{TAG_TRUE}else{TAG_FALSE},self.control),DslValue::Number(Number::UInt(value))=>{output.byte(TAG_UINT,self.control)?;output.varint(*value,self.control)},DslValue::Number(Number::Int(value))=>{output.byte(TAG_INT,self.control)?;output.signed(*value,self.control)},DslValue::Number(Number::Float(value))=>{output.byte(TAG_F64,self.control)?;output.bytes(&value.to_le_bytes(),self.control)},DslValue::String(text)=>self.text(text,false,output),DslValue::Bytes(bytes)=>self.bytes(bytes,output),
