    }}
    fn node(&mut self,node:&WireNode,output:&mut Output)->Result<(),OutputError>{output.byte(u8::from(node.kind.is_some())|(u8::from(node.port.is_some())<<1),self.control)?;self.text(&node.id,false,output)?;if let Some(text)=&node.kind{self.text(text,false,output)?;}if let Some(text)=&node.port{self.text(text,false,output)?;}Ok(())}
    fn wire(&mut self,wire:&WireValue,depth:u16,output:&mut Output)->Result<(),OutputError>{let label=!wire.edge_label.is_empty();let mut presence=u8::from(wire.edge.is_some())|(u8::from(label)<<2);if wire.edge.as_ref().is_some_and(|(directed,_)|*directed){presence|=2;}output.byte(presence,self.control)?;self.node(&wire.from,output)?;if let Some((_,node))=&wire.edge{self.node(node,output)?;}if label{output.byte(u8::from(wire.edge_label.id.is_some())|(u8::from(wire.edge_label.kind.is_some())<<1),self.control)?;if let Some(text)=&wire.edge_label.id{self.text(text,false,output)?;}if let Some(text)=&wire.edge_label.kind{self.text(text,false,output)?;}}self.dynamic(&wire.properties,depth+1,output)}
